toolArgs.file_text:
@page "/dashboard"
@using sv_d2cf67eaf3a3405c87ce9133cef4f6cd.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="alert alert-info">
    <strong>Current Warehouse:</strong> @WarehouseState.CurrentWarehouseName
    <span class="text-muted">(@WarehouseState.CurrentWarehouseId)</span>
</div>

<div class="row">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text display-4">
                    @if (_lowStockCount > 0)
                    {
                        <span class="text-danger">@_lowStockCount</span>
                    }
                    else
                    {
                        <span class="text-success">0</span>
                    }
                </p>
                <p class="text-muted">Items below minimum level</p>
                <p class="text-muted small">
                    Last checked: @(_lastChecked?.ToString("HH:mm:ss") ?? "—")
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-8">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Polling Status</h5>
                <p>
                    <span class="badge @(_isPolling ? "bg-success" : "bg-secondary")">
                        @(_isPolling ? "Active" : "Stopped")
                    </span>
                    — refreshing every 10 seconds
                </p>
                <p class="text-muted small">
                    Polling starts when this page loads and stops when you navigate away.
                    All subscribed components (including the sidebar badge) update simultaneously.
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private int _lowStockCount;
    private DateTime? _lastChecked;
    private bool _isPolling;
    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertCountChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await StartPollingAsync();
        }
    }

    private async Task StartPollingAsync()
    {
        _cts?.Cancel();
        _cts = new CancellationTokenSource();
        _isPolling = true;
        var token = _cts.Token;

        // Immediate first poll
        await PollAsync();

        _ = Task.Run(async () =>
        {
            while (!token.IsCancellationRequested)
            {
                try
                {
                    await Task.Delay(TimeSpan.FromSeconds(10), token);
                    await PollAsync();
                }
                catch (OperationCanceledException)
                {
                    break;
                }
            }
        }, token);
    }

    private async Task PollAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        _lastChecked = DateTime.Now;
        _lowStockCount = count;

        // Notify ALL subscribers (sidebar badge, other components)
        AlertService.UpdateAlertCount(count);

        await InvokeAsync(StateHasChanged);
    }

    private async void OnWarehouseChanged()
    {
        // Restart polling for the new warehouse
        await StartPollingAsync();
    }

    private void OnAlertCountChanged()
    {
        _lowStockCount = AlertService.LastLowStockCount;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _isPolling = false;
        _cts?.Cancel();
        _cts?.Dispose();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertCountChanged;
    }
}

